groovy.script:
def store = PORTAL_CONTEXT.getBean('newsStore')
def dataSource = PORTAL_CONTEXT.getBean('dataSource')
def dir = new File(exportDir)
dir.mkdirs()
def ids = []
def roles = [:]
def connection = dataSource.getConnection()
try {
    def statement = connection.prepareStatement(
        "select NEWS_ID from NEWS_DEFINITION where NEWS_LISTING_TYPE = 'PD'")
    def rows = statement.executeQuery()
    while (rows.next()) {
        ids.add(new Long(rows.getLong(1)))
    }
    rows.close()
    statement.close()
    statement = connection.prepareStatement(
        "select ROLE_NAME from NEWS_ROLE where NEWS_ID = ?")
    for (id in ids) {
        statement.setLong(1, id.longValue())
        rows = statement.executeQuery()
        def names = new TreeSet()
        while (rows.next()) {
            names.add(rows.getString(1))
        }
        rows.close()
        roles.put(id, names)
    }
    statement.close()
} finally {
    connection.close()
}
for (id in ids) {
    def definition = store.getPredefinedNewsDefinition(id)
    def document = org.dom4j.DocumentHelper.createDocument()
    def root = document.addElement('predefined-news')
    root.addAttribute('script',
        'classpath:/org/jasig/portlet/newsreader/io/import-PredefinedNewsDefinition_v1-0.crn.xml')
    root.addElement('fname').setText(definition.getFname() == null ? '' : definition.getFname())
    root.addElement('className').setText(definition.getClassName())
    root.addElement('name').setText(definition.getName())
    def parameters = root.addElement('parameters')
    def parameterMap = new TreeMap(definition.getParameters())
    for (entry in parameterMap.entrySet()) {
        def parameter = parameters.addElement('parameter')
        parameter.addAttribute('name', entry.getKey())
        parameter.setText(entry.getValue())
    }
    def predefinedRoles = root.addElement('predefinedRoles')
    for (role in roles.get(id)) {
        predefinedRoles.addElement('role').setText(role)
    }
    // The Groovy in the WAR is 1.5: keep to its syntax
    def fileName = definition.getFname()
    if (fileName == null || fileName.length() == 0) {
        fileName = 'news-' + id
    }
    def file = new File(dir, fileName.replaceAll('[^A-Za-z0-9._-]', '_') + '.pnd.xml')
    def format = org.dom4j.io.OutputFormat.createPrettyPrint()
    format.setEncoding('UTF-8')
    def out = new FileOutputStream(file)
    try {
        def writer = new org.dom4j.io.XMLWriter(out, format)
        writer.write(document)
        writer.flush()
    } finally {
        out.close()
    }
    println(EXPORT_LOG_PREFIX + 'Exported ' + file)
}
